const statusClasses: Record<string, string> = { 'Recruiting': 'green', 'Not recruiting': 'gray', 'Unknown': 'blue', 'Needs verification': 'amber', 'Pending': 'amber', 'Approved': 'green', 'Rejected': 'red', 'Open': 'green', 'Closed': 'gray', 'Emailed': 'blue', 'Replied': 'teal', 'Interview': 'purple', 'Accepted': 'green' };
const formatDate = (value: string) => value ? new Date(`${value}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : 'Not set';

function StatusPill({ value }: { value: string }) { return <span className={`status-pill ${statusClasses[value] || 'blue'}`}><i />{value}</span>; }
function Button({ children, onClick, variant = 'primary', size = 'md', disabled = false, type = 'button' }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'quiet' | 'danger' | 'outline'; size?: 'sm' | 'md'; disabled?: boolean; type?: 'button' | 'submit' }) { return <button type={type} disabled={disabled} onClick={onClick} className={`btn ${variant} ${size}`}>{children}</button>; }
function Panel({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section>; }
function Heading({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="heading-actions">{actions}</div>}</div>; }
function Avatar({ initials, tone = 'lavender', size = 'md' }: { initials: string; tone?: string; size?: 'sm' | 'md' | 'lg' }) { return <div className={`avatar ${tone} ${size}`}>{initials}</div>; }
function Metric({ label, value, note, icon, tone = 'purple' }: { label: string; value: string; note: string; icon: ReactNode; tone?: string }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><span>{label}</span><strong>{value}</strong><small>{note}</small></div>; }
function SourceTag({ source }: { source: Provenance }) { return <span className={`source-tag ${source.toLowerCase().replace(' ', '-')}`}><i />{source}</span>; }
function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Search size={20} /></div><b>{title}</b><p>{body}</p>{action}</div>; }

